import{_ as e,o as t,c as i,a2 as a}from"./chunks/framework.NpvCl_7q.js";const k=JSON.parse('{"title":"Testing","description":"","frontmatter":{},"headers":[],"relativePath":"contributing/testing.md","filePath":"contributing/testing.md","lastUpdated":1792608207000}'),n={name:"contributing/testing.md"};function o(l,s,d,r,h,p){return t(),i("div",null,[...s[0]||(s[0]=[a(`<h1 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h1><p>MasonKit has three layers of tests. The rule that keeps bugs cheap: <strong>a unit or parsing bug must fail in the fast Node suite before it is allowed to reach a device.</strong> Most bugs in the CSS value layer (wrong units, a shorthand mislabelling a bare number, a percentage off by 100x) are catchable in milliseconds there.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Command</th><th>Needs</th></tr></thead><tbody><tr><td>TypeScript value layer</td><td><code>npm test</code></td><td>Node only</td></tr><tr><td>Generated code checks</td><td><code>npm run test:keys</code>, <code>npm run test:jsx-types</code></td><td>Node only</td></tr><tr><td>Rust engine</td><td><code>npm run test:rust</code></td><td>Rust</td></tr><tr><td>Kotlin / Swift unit tests</td><td>Gradle / <code>xcodebuild test</code></td><td>JDK + Android SDK, or Xcode</td></tr><tr><td>Layout against a real browser</td><td>WebSpec in <code>apps/demo-solid</code></td><td>A device or simulator</td></tr></tbody></table><h2 id="node-suite-npm-test" tabindex="-1">Node suite (<code>npm test</code>) <a class="header-anchor" href="#node-suite-npm-test" aria-label="Permalink to &quot;Node suite (\`npm test\`)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # run once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:watch</span></span></code></pre></div><p>Vitest runs every <code>packages/**/*.spec.ts</code> and <code>tools/testing/**/*.spec.ts</code> in Node, with no device and no native build. The config is <code>tools/testing/vitest.config.ts</code>; helpers live in <code>tools/testing/mason-test-kit/</code>.</p><p>It works without touching production code:</p><ul><li><strong>The style buffer is a plain <code>ArrayBuffer</code>.</strong> <code>style-under-test.ts</code> hands a <code>Style</code> a buffer sized from the StyleKeys schema, so setters write real bytes you can read back.</li><li><strong>Offsets are read from the source</strong>, not copied, so a test can&#39;t drift from <code>style.ts</code>.</li><li><strong><code>@nativescript/core</code> is stubbed just enough to load.</strong> <code>ns-core-stub.ts</code> re-exports core&#39;s real classes from their leaf modules, and <code>platform-suffix-resolver.ts</code> resolves core&#39;s platform-suffixed imports. The <code>windows</code> and <code>windows-sync</code> projects also prefer MasonKit&#39;s own <code>*.windows.ts</code> modules, as the Windows build does.</li></ul><p>The suite is split into Vitest projects. Most specs run platform-neutral (<code>__ANDROID__</code>, <code>__APPLE__</code> and <code>__WINDOWS__</code> all false). <code>*.android.spec.ts</code> and <code>*.windows.spec.ts</code> run with their platform flag set against mocked natives, and <code>style-native-sync.spec.ts</code> runs once per platform.</p><p>Useful guards to know about:</p><ul><li><code>style.spec.ts</code> runs the unit table at screen scales 1, 2 and 3. At scale 1 a px/dip mix-up is invisible.</li><li><code>diagnostics.spec.ts</code> feeds a stylesheet&#39;s worth of declarations through the parsers and snapshots what was dropped, so a regression shows up as a new line.</li><li><code>properties.spec.ts</code> fails when a new CSS property collides with one NativeScript core already registers without being routed for plain views.</li><li><code>tools/testing/core-view-unaffected.spec.ts</code> checks that installing MasonKit doesn&#39;t change how plain NativeScript views handle CSS.</li></ul><div class="tip custom-block"><p class="custom-block-title">What not to test in Node</p><p>NativeScript core&#39;s selector engine and <code>CssState</code> need a live view tree and the application lifecycle. Selector matching stays on-device.</p></div><h2 id="generated-code-checks" tabindex="-1">Generated code checks <a class="header-anchor" href="#generated-code-checks" aria-label="Permalink to &quot;Generated code checks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:keys</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # StyleKeys/StateKeys blocks match style-keys.schema</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:jsx-types</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # JSX intrinsic typings match the element registry</span></span></code></pre></div><p>Both fail in CI when a generated file is stale or was edited by hand. Fix them by running the generator (<code>npm run gen:style-keys</code>, <code>npm run gen:jsx-types</code>) and committing the result.</p><h2 id="rust-npm-run-test-rust" tabindex="-1">Rust (<code>npm run test:rust</code>) <a class="header-anchor" href="#rust-npm-run-test-rust" aria-label="Permalink to &quot;Rust (\`npm run test:rust\`)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:rust</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # cargo test -p mason-core --all-targets</span></span></code></pre></div><p>The integration tests in <code>crates/mason-core/tests/</code> cover flex, grid, block, inline flow, floats and writing modes, include batches ported from the Web Platform Tests (<code>wpt_*.rs</code>), and pin regressions in engine behaviour MasonKit depends on. CI also runs <code>cargo fmt --all -- --check</code>.</p><h2 id="kotlin-and-swift" tabindex="-1">Kotlin and Swift <a class="header-anchor" href="#kotlin-and-swift" aria-label="Permalink to &quot;Kotlin and Swift&quot;">​</a></h2><p>Android JVM unit tests (parsers, geometry, no device):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/nativescript-masonkit/src-native/mason-android</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :masonkit:testReleaseUnitTest</span></span></code></pre></div><p>Tests that load <code>libmasonnative</code> or use Android&#39;s text classes live in <code>androidTest</code> and run on a device or emulator:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :masonkit:connectedReleaseAndroidTest</span></span></code></pre></div><p>An instrumented run stops at the first native crash, so when chasing one, run a single class:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./gradlew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> :masonkit:connectedReleaseAndroidTest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -Pandroid.testInstrumentationRunnerArguments.class=org.nativescript.mason.masonkit.ScrollInstrumentedTest</span></span></code></pre></div><p>iOS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/nativescript-masonkit/src-native/mason-ios/Mason</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xcodebuild</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Mason.xcodeproj</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -scheme</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Mason</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -destination</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;platform=iOS Simulator,name=iPhone 16&#39;</span></span></code></pre></div><h2 id="webspec-layout-against-chromium" tabindex="-1">WebSpec: layout against Chromium <a class="header-anchor" href="#webspec-layout-against-chromium" aria-label="Permalink to &quot;WebSpec: layout against Chromium&quot;">​</a></h2><p>WebSpec compares MasonKit&#39;s layout with a real browser. <code>tools/scripts/webspec-tests/generate.mjs</code> renders each fixture in headless Chromium (through Playwright), records the layout rect of every box, and writes the result to <code>apps/demo-solid/src/webspec/fixtures.generated.json</code>. The demo-solid app replays each fixture with MasonKit on a device and compares rects.</p><p>The fixtures are the vendored taffy/WPT flex and grid tests in <code>tools/scripts/gentests/taffy_tests</code>, plus hand-written ones in <code>tools/scripts/gentests/custom_element_tests</code> that check tag defaults such as heading and paragraph margins.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chromium</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # once</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen:webspec</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # regenerate the committed ground truth</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen:webspec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # fail if it is stale (the nightly job)</span></span></code></pre></div><p>Running it on a device:</p><ol><li>Rebuild the package (<code>npx nx run nativescript-masonkit:build.all</code>).</li><li>Run <code>apps/demo-solid</code> (<code>ns run ios</code> or <code>ns run android</code>). WebSpec is the initial route.</li><li>The run starts when the screen opens; <strong>Run All</strong> restarts it.</li></ol><p>When a run finishes, the app logs a <code>WEBSPEC_RESULT {...}</code> line with pass and fail counts and writes the full failure list to <code>webspec-failures.json</code> in the app&#39;s documents folder. On Android you can pull it with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run-as</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> files/webspec-failures.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> webspec-failures.json</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Flat 0x0 failures</p><p>A fixture where every box, root included, comes back 0x0 usually means the device stalled (a slow or overloaded emulator), not a layout bug. Re-run on an idle device before investigating. A real regression shows a wrong but non-zero rect.</p></div><p>The fixtures use the Ahem test font, which ships in <code>apps/demo-solid/src/fonts/</code> so text metrics match the browser.</p>`,37)])])}const g=e(n,[["render",o]]);export{k as __pageData,g as default};
